#!/bin/bash
set -o pipefail
python scripts/cluster_run.py --target house --name compass-capture --minutes 30 --arm-block fam 'mkdir -p out/compass_standin_r3 && source .venv/bin/activate && python -c '"'"'import torch; assert torch.cuda.is_available()'"'"' && ( python scripts/compass_driver_cuda_check.py --out out/compass_standin_r3/cuda_checks.json && FLYVERSE_CUDA_TESTS=1 python -m pytest tests/test_cuda.py -q -p no:cacheprovider && python scripts/compass_driver_profile.py --native --out out/compass_standin_r3/profile_native.json && python scripts/compass_driver_profile.py --native --module-eager --out out/compass_standin_r3/profile_eager.json && python scripts/compass_driver_trace.py --out out/compass_standin_r3/trace && python scripts/probe_compass_driver.py --mode instrumented --seed 10 --out out/compass_standin_r3/instrumented_s10 && python scripts/probe_compass_driver.py --mode instrumented --seed 11 --out out/compass_standin_r3/instrumented_s11 && python scripts/probe_compass_driver.py --mode instrumented --seed 12 --out out/compass_standin_r3/instrumented_s12 && python scripts/probe_compass_driver.py --mode instrumented --seed 13 --out out/compass_standin_r3/instrumented_s13 && python scripts/probe_compass_driver.py --mode instrumented --seed 14 --out out/compass_standin_r3/instrumented_s14 && python scripts/probe_compass_driver.py --mode instrumented --seed 15 --out out/compass_standin_r3/instrumented_s15 && python scripts/compass_driver_room.py --mode instrumented --seed 10 --scheduler eager --out out/compass_standin_r3/room_eager_a && python scripts/compass_driver_room.py --mode instrumented --seed 10 --scheduler eager --out out/compass_standin_r3/room_eager_b && python scripts/compass_driver_room.py --mode instrumented --seed 10 --scheduler captured --out out/compass_standin_r3/room_instrumented && python scripts/compass_driver_room.py --mode raw --seed 10 --native --out out/compass_standin_r3/room_native_raw && python scripts/compass_driver_room.py --mode instrumented --seed 10 --native --out out/compass_standin_r3/room_native_instrumented ) > out/compass_standin_r3/run.txt 2>&1; st=$?; tail -8 out/compass_standin_r3/run.txt; exit $st' --fetch out/compass_standin_r3/ 2>&1 | tee out/compass_standin_r3/client_stdout.txt
